svg.script:
function launchApp() {
      const appWindow = window.open("about:blank", "_blank");
      if (!appWindow) {
        document.getElementById("status").textContent = "Pop-up blocked. Allow pop-ups for this page, then try again.";
        return;
      }
      appWindow.opener = null;
      appWindow.document.open();
      appWindow.document.write(document.getElementById("app-source").textContent);
      appWindow.document.close();
      document.getElementById("status").textContent = "Study hub opened in a new tab.";
    }
